<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';
import {useResearch} from '../stores/research';
import {useAuth} from '../stores/auth';
import {useTask} from '../hooks/useTask';
import {usePolling} from '../hooks/usePolling';
import {num,rank,percent,date} from '../utils/format';
import {directions,recalcStatus as recalcStatusMap} from '../constants/enums';
import PageHeading from '../components/common/PageHeading.vue';
import ErrorNotice from '../components/common/ErrorNotice.vue';
import StatusBadge from '../components/common/StatusBadge.vue';
import RunSelect from '../components/RunSelect.vue';
import WeightStrip from '../components/WeightStrip.vue';
import RankIntervals from '../components/RankIntervals.vue';
import StaleBadge from '../components/StaleBadge.vue';
import ImpactScope from '../components/ImpactScope.vue';
import TradeoffCompare from '../components/TradeoffCompare.vue';
const research=useResearch(),auth=useAuth(),{error,busy,perform}=useTask();
const tab=ref('score'),code=ref(''),page=ref(0),limit=ref(12),showImpact=ref(false);
const r=computed(()=>research.current?.status==='completed'?research.current.result:null);
const ordered=computed(()=>r.value?[...r.value.samples].sort((a,b)=>a.rank-b.rank):[]);
const index=computed(()=>Math.max(0,r.value?.samples.findIndex(s=>s.code===code.value)??0));
const sample=computed(()=>r.value?.samples[index.value]);
const staleReport=computed(()=>research.current?research.staleById.get(research.current.id):undefined);
const family=computed(()=>research.current?research.chainOf(research.current.id):[]);
const rootId=computed(()=>research.current?.recalc_of_id||research.current?.id||0);
const latestRecalc=computed(()=>rootId.value?research.recalcByRoot.get(rootId.value):undefined);
watch(()=>research.selected,()=>{page.value=0;showImpact.value=false});
watch(r,value=>{if(!value)return;if(!value.samples.some(s=>s.code===code.value))code.value=value.samples[0]?.code||'';page.value=0});
onMounted(()=>perform(async()=>{await research.loadRuns();await research.loadStale();await research.select(research.selected)}));
usePolling(async()=>{await research.loadRuns();await research.loadStale();const summary=research.runs.find(r=>r.id===research.selected);if(summary&&summary.status!==research.current?.status)await research.select(summary.id)});
async function recalc(){if(research.current)await research.recalculate(research.current.recalc_of_id||research.current.id);}
async function retry(){if(latestRecalc.value)await research.retry(latestRecalc.value.id);}
const latestRecalcLabel=computed(()=>{const l=latestRecalc.value;if(!l)return'';return (l.recalc_status&&recalcStatusMap[l.recalc_status as keyof typeof recalcStatusMap])||l.status;});
const latestRecalcFailed=computed(()=>latestRecalc.value?.status==='failed');
const latestRecalcActive=computed(()=>{const s=latestRecalc.value?.status;return s==='queued'||s==='running';});
const latestRecalcDone=computed(()=>latestRecalc.value?.status==='completed');
</script>
<template><PageHeading no="04" title="结果与扰动" sub="贴近度依赖当前候选集合和偏好；请把中心名次放回情景范围里阅读。"/><RunSelect/><ErrorNotice :error="error"/><div v-if="!research.current" class="empty"><h2>等待一份研究结果</h2><p>先到权衡配置提交任务；已完成任务可从上方选择。</p><RouterLink to="/runs">前往配置 →</RouterLink></div><div v-else-if="!r" class="empty"><StatusBadge :status="research.current.status"/><h2>{{research.current.name}}</h2><p>{{research.current.error||'任务还在演算队列中，完成后自动刷新。'}}</p><RouterLink to="/runs">返回队列核对 →</RouterLink></div><template v-if="r&&research.current">
  <div v-if="research.current.recalc_of_id" class="lineage-banner"><b>数据重算 v{{research.current.recalc_seq}}</b><span>依据原始任务 #{{research.current.recalc_of_id}}，沿用其中心权重、κ、seed 与情景数；旧结果保留为对照。</span><button class="text-link" @click="perform(()=>research.select(research.current!.recalc_of_id!))">打开原始权衡 #{{research.current.recalc_of_id}} ↗</button></div>
  <div v-if="staleReport?.stale" class="stale-banner"><div><StaleBadge :run-id="research.current.id"/><b>源数据已更新，本页结果基于修订前冻结快照</b><p class="muted">受影响试样 {{staleReport.affected_sample_ids.length}} 份；试样变化 {{staleReport.sample_changes.length}} 项、指标变化 {{staleReport.criterion_changes.length}} 项。旧结果与已批准计划继续保留原依据。</p></div><div class="button-row"><button class="small-button" @click="showImpact=!showImpact">{{showImpact?'收起影响范围':'查看影响范围'}}</button><button v-if="auth.canEdit&&!latestRecalcActive" class="primary" :disabled="busy" @click="perform(recalc)">按原偏好重算 →</button><button v-if="auth.canEdit&&latestRecalcFailed" class="primary" :disabled="busy" @click="perform(retry)">重试重算 →</button></div></div>
  <div v-if="staleReport?.stale&&latestRecalc" class="recalc-line"><small>最新重算 #{{latestRecalc.id}} · {{latestRecalcLabel}} · {{date(latestRecalc.created_at)}}</small><button v-if="latestRecalcDone" class="text-link" @click="perform(()=>research.select(latestRecalc!.id))">查看新权衡对照 ↗</button><p v-if="latestRecalcFailed" class="error-text">重算失败：{{latestRecalc.error}}（可重试，旧计划分发不受影响）</p><p v-if="latestRecalcActive" class="working">重算进行中，页面每2.5秒刷新进度。</p></div>
  <ImpactScope v-if="showImpact&&staleReport" :report="staleReport"/>
  <div v-if="family.length>1" class="family-strip"><small>版本链：</small><button v-for="m in family" :key="m.id" :class="['chain-chip',{active:m.id===research.current.id}]" @click="perform(()=>research.select(m.id))">#{{m.id}} v{{m.recalc_seq||0}} · {{m.status==='completed'?'完成':m.status}}</button></div>
  <div class="result-byline"><b>#{{research.current.id}} {{research.current.name}}</b><span>{{r.samples.length}}候选 · κ {{r.concentration}} · {{r.repeats}}情景 · seed {{r.seed}}</span></div><WeightStrip :criteria="r.criteria" :weights="r.center_weights"/><p v-if="r.all_indistinguishable" class="notice">中心权重下全部候选不可区分：贴近度0.5、平均并列名次，不给出编号顺序偏好。</p>
  <div class="result-tabs"><button :class="{active:tab==='score'}" @click="tab='score'">贴近度与距离</button><button :class="{active:tab==='sensitivity'}" @click="tab='sensitivity'">权重情景名次</button><button :class="{active:tab==='compare'}" @click="tab='compare'">新旧权衡对照</button><button :class="{active:tab==='archive'}" @click="tab='archive'">1000次情景留档</button></div>
  <TradeoffCompare v-if="tab==='compare'" :run="research.current"/>
<div v-if="tab==='score'" class="score-spread"><section><h2 class="ruled-title">当前偏好下的贴近度 <small>不是性能概率</small></h2><div class="score-ledger"><button v-for="s in ordered" :key="s.id" :class="{selected:s.id===sample?.id}" @click="code=s.code"><span class="sample-rank">{{rank(s.rank)}}</span><span><b>{{s.code}} {{s.name}}</b><i class="score-track"><i :style="{width:percent(s.score)}"/></i></span><strong>{{num(s.score,4)}}</strong></button></div></section><section v-if="sample" class="distance-sheet"><p class="eyebrow">FOLLOW ONE MATERIAL / 拆开看一份试样</p><h2>{{sample.code}} · {{sample.name}}</h2><div class="distance-pair"><div><small>到正理想点 D⁺</small><b>{{num(sample.distance_best,6)}}</b></div><div><small>到负理想点 D⁻</small><b>{{num(sample.distance_worst,6)}}</b></div><div><small>贴近度 C</small><b>{{num(sample.score,6)}}</b></div></div><p class="formula">C = D⁻ / (D⁺ + D⁻)</p><p class="muted">理想点来自本次候选集合。贴近1仅表示靠近这组指标的相对理想点，不是合格概率或绝对品质。</p><div class="table-scroll"><table class="distance-table"><thead><tr><th>指标 / 方向</th><th>原始</th><th>L2标准化</th><th>加权</th><th>正理想</th><th>负理想</th></tr></thead><tbody><tr v-for="(c,j) in r.criteria" :key="c.code"><td>{{c.name}}<small>{{directions[c.direction]}}</small></td><td>{{num(sample[c.code],4)}}</td><td>{{num(sample.normalized[j],5)}}</td><td>{{num(sample.weighted[j],5)}}</td><td>{{num(r.ideal_best[j],5)}}</td><td>{{num(r.ideal_worst[j],5)}}</td></tr></tbody></table></div><details class="edit-fold"><summary>逐列范数、零列与常量处理</summary><article class="column-note" v-for="(c,j) in r.criteria" :key="c.code"><b>{{c.name}}</b><p>范数 {{r.columns[j].norm}} / 零范数 {{r.columns[j].zero_norm?'是':'否'}} / 常量 {{r.columns[j].constant?'是':'否'}}</p><small>{{r.columns[j].policy}}</small></article></details></section></div><div v-if="tab==='sensitivity'" class="sensitivity-spread"><section><div class="section-line"><h2>权重变化时，名次如何移动</h2><select aria-label="显示候选数量" v-model.number="limit"><option :value="12">中心排名前12项</option><option :value="r.samples.length">全部候选</option></select></div><p class="muted">当前显示{{Math.min(limit,r.samples.length)}}项，名次均在完整{{r.samples.length}}项候选中计算。</p><RankIntervals :rows="ordered.slice(0,limit)" :total="r.samples.length"/><p class="plot-caption">━ 横线：情景名次2.5%–97.5%经验分位　● 中心权重名次</p><p class="muted">范围是偏好情景的描述，不是统计置信区间。分位线性插值可为小数；贴近度计算值完全相等才平均并列，不按编号打破并列。窄屏图可横向滚动。</p></section><aside v-if="sample" class="scenario-focus"><p class="eyebrow">READ THE TRADE-OFF / 看一份材料</p><label>试样<select aria-label="情景分布试样" v-model="code"><option v-for="s in r.samples" :key="s.id" :value="s.code">{{s.code}} {{s.name}}</option></select></label><h2>{{sample.code}}</h2><p>{{sample.name}}</p><div class="rank-summary"><div><small>真实最好 / 最差</small><b>{{rank(sample.rank_min)}} / {{rank(sample.rank_max)}}</b></div><div><small>首位分摊频率</small><b>{{percent(sample.first_share)}}</b></div></div><p class="muted">并列首位均分一份；这是1000个权重情景的频率，不是“最优材料”的后验概率。</p><div class="frequency-bars"><div v-for="(count,pos) in sample.rank_frequency" :key="pos"><span>第{{pos}}名</span><i :style="{width:percent(count/r.repeats)}"/><b>{{count}}次</b></div></div><aside class="margin-note">κ {{r.concentration}}；α = κ × 正中心权重。记录中含零权重的情景 {{r.zero_weight_scenarios}} 次，按合法非负权重计算。</aside></aside></div><section v-if="tab==='archive'"><h2 class="ruled-title">每个偏好情景，原样留下 <small>{{r.draws.length}} / {{r.repeats}}</small></h2><label class="inline-select">观察试样<select aria-label="留档观察试样" v-model="code"><option v-for="s in r.samples" :value="s.code" :key="s.id">{{s.code}} {{s.name}}</option></select></label><p class="muted">每页25次；展开任一行可见该情景全部{{r.samples.length}}份试样的贴近度与平均名次。</p><div class="table-scroll"><table class="scenario-table"><thead><tr><th>情景</th><th v-for="c in r.criteria" :key="c.code">{{c.name}}权重</th><th>{{sample?.code}}贴近度</th><th>平均名次</th></tr></thead><tbody><tr v-for="d in r.draws.slice(page*25,(page+1)*25)" :key="d.repeat"><td><details><summary>#{{d.repeat}}</summary><pre>{{JSON.stringify(d,null,2)}}</pre></details></td><td v-for="(w,j) in d.weights" :key="j">{{num(w,5)}}</td><td>{{num(d.scores[index],6)}}</td><td>{{rank(d.ranks[index])}}</td></tr></tbody></table></div><div class="button-row"><button :disabled="page===0" @click="page--">上一页</button><span>{{page+1}} / {{Math.ceil(r.draws.length/25)}}</span><button :disabled="(page+1)*25>=r.draws.length" @click="page++">下一页</button></div></section><div class="result-boundary"><b>研究边注</b><p>权重扰动是偏好敏感性情景，不是统计置信、贝叶斯后验或采购建议。候选增删、指标平移可能逆转排名；对声学性能与实际施工仍需独立试样。</p><RouterLink to="/notes">写下试样验证问题 →</RouterLink></div><div class="fingerprint">冻结快照 SHA256 <code>{{r.fingerprint}}</code><span v-if="research.current.source_fingerprint" class="muted">　源数据指纹 <code>{{research.current.source_fingerprint.slice(0,16)}}…</code></span></div></template></template>
